<?php require_once __DIR__.'/../lib/helpers.php'; require_login(); $conn=db(); $q=$conn->query("SELECT p.no_pinjaman, a.nama, j.tanggal_jatuh_tempo, DATEDIFF(CURDATE(), j.tanggal_jatuh_tempo) telat, j.total_tagih FROM ksp_jadwal_angsuran j JOIN ksp_pinjaman p ON p.id=j.pinjaman_id JOIN ksp_anggota a ON a.id=p.anggota_id WHERE j.status='belum' AND j.tanggal_jatuh_tempo < CURDATE() ORDER BY j.tanggal_jatuh_tempo"); ?><!doctype html><html><head><meta charset='utf-8'><title>Laporan Aging</title><style>@media print{@page{size:A4;margin:12mm}} body{font-family:Arial;font-size:11pt} table{width:100%;border-collapse:collapse} th,td{border:1px solid #333;padding:6px 8px}</style></head><body onload='window.print()'><h3>Aging Tunggakan (per <?php echo date('Y-m-d'); ?>)</h3><table><thead><tr><th>No Pinjaman</th><th>Nama</th><th>JT</th><th>Telat (hari)</th><th>Tagih</th></tr></thead><tbody><?php $sum=0; while($r=$q->fetch_assoc()): $sum+=$r['total_tagih']; ?><tr><td><?php echo htmlspecialchars($r['no_pinjaman']); ?></td><td><?php echo htmlspecialchars($r['nama']); ?></td><td><?php echo htmlspecialchars($r['tanggal_jatuh_tempo']); ?></td><td><?php echo (int)$r['telat']; ?></td><td>Rp <?php echo rupiah($r['total_tagih']); ?></td></tr><?php endwhile; ?><tr><td colspan='4' style='text-align:right'><b>Total</b></td><td><b>Rp <?php echo rupiah($sum); ?></b></td></tr></tbody></table></body></html>